from pathlib import Path
p=Path('Code1/Code1.cpp'); s=p.read_text()
needle='// E360..E3B2: signed decimal parser.'
assert needle in s and 'function_e280' not in s
block='''// E280..E2C2: install the E2C3 INT 24h trampoline while preserving the caller-supplied far callback at 5102:5106.\n// Runtime modes 2..4 use the extender-specific INT 21h AX=2506h, CL=24h form; all other modes use AH=25h, AL=24h. The encoded routine returns EAX=0.\nstruct Int24InstallBoundary{void(*store_callback)(u32,u16)=nullptr;u8(*runtime_mode)()=nullptr;void(*install_extender_vector)(u8,u32)=nullptr;void(*install_dos_vector)(u8,u32)=nullptr;};\n[[nodiscard]]u32 function_e280(Int24InstallBoundary&b,u32 callback_offset,u32 callback_selector)noexcept{if(b.store_callback)b.store_callback(callback_offset,static_cast<u16>(callback_selector));const u8 mode=b.runtime_mode?b.runtime_mode():0u;if(mode>=2u&&mode<=4u){if(b.install_extender_vector)b.install_extender_vector(0x24u,0xE2C3u);}else if(b.install_dos_vector)b.install_dos_vector(0x24u,0xE2C3u);return 0u;}\nstatic_assert(0xE2C3u-0xE280u==67u);\n\n'''
s=s.replace(needle,block+needle).replace('constexpr u32 kVerifiedTranslatedBytes=9074u;','constexpr u32 kVerifiedTranslatedBytes=9141u;')
assert 'kVerifiedTranslatedBytes=9141u' in s
p.write_text(s)
q=Path('Code1/PROGRESS.md'); t=q.read_text()
t=t.replace('12.88%25-red','12.98%25-red').replace('**Verified conversion:** 12.88%','**Verified conversion:** 12.98%').replace('**Remaining:** 87.12%','**Remaining:** 87.02%').replace('Current verified translated bytes: **9,074**.','Current verified translated bytes: **9,141**.').replace('Raw coverage: **12.8888%**, displayed as **12.88%**.','Raw coverage: **12.9840%**, displayed as **12.98%**.').replace('Total integrated verified translated bytes: **9,074**.','Total integrated verified translated bytes: **9,141**.')
t=t.replace('- Runtime object clone `E0D0..E173`: **164 bytes**.','- Runtime object clone `E0D0..E173`: **164 bytes**.\n- INT 24h trampoline installer `E280..E2C2`: **67 bytes**.')
t=t.replace('leaving **281 unique unintegrated bytes**','leaving **214 unique unintegrated bytes**').replace('staging pool is **1,566 bytes**: 747 startup + 595 remaining DOS/CRT + 224 remaining E280..E35F','staging pool is **1,499 bytes**: 747 startup + 595 remaining DOS/CRT + 157 remaining E2C3..E35F')
